package com.team2.wellness.engagement.notification.api;
import com.team2.wellness.engagement.notification.application.NotificationService; import com.team2.wellness.engagement.notification.domain.Notification; import com.team2.wellness.engagement.port.out.CurrentUserPort; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/engagement/notifications") public class NotificationController {final NotificationService notifications;final CurrentUserPort user; public NotificationController(NotificationService n,CurrentUserPort u){notifications=n;user=u;} @GetMapping List<Notification> page(@RequestParam(required=false)Instant cursorCreatedAt,@RequestParam(required=false)UUID cursorId,@RequestParam(defaultValue="30")int size){return notifications.page(user.currentUserId(),cursorCreatedAt,cursorId,size);}@PatchMapping("/{id}/read")@ResponseStatus(HttpStatus.NO_CONTENT)void read(@PathVariable UUID id){notifications.read(user.currentUserId(),id);}@PatchMapping("/read-all")@ResponseStatus(HttpStatus.NO_CONTENT)void readAll(){notifications.readAll(user.currentUserId());}}
